import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

SUM_BWD_DTYPES = [torch.float32]
if flag_gems.runtime.device.support_fp64:
    SUM_BWD_DTYPES.append(torch.float64)

# (shape, sparse_dim, nnz, dims)
SUM_BWD_CASES = [
    ((8, 6, 4), 3, 80, [0, 1]),
    ((8, 6, 4), 3, 80, [1]),
    ((8, 6, 4), 3, 80, [2]),
    ((16, 32), 2, 64, [0]),
    ((8, 6, 4), 2, 80, [0]),  # hybrid COO, dense dims kept
]


def _make_sparse_coo(shape, sparse_dim, nnz, dtype, device, seed=0, coalesced=True):
    g = torch.Generator(device="cpu").manual_seed(seed)
    idx = torch.stack(
        [torch.randint(0, s, (nnz,), generator=g) for s in shape[:sparse_dim]]
    ).to(device)
    values = torch.randn(
        (nnz,) + tuple(shape[sparse_dim:]), dtype=dtype, generator=g
    ).to(device)
    t = torch.sparse_coo_tensor(idx, values, shape, device=device, dtype=dtype)
    return t.coalesce() if coalesced else t


def _assert_sparse_close(res, ref, dtype):
    assert res.shape == ref.shape
    assert res.sparse_dim() == ref.sparse_dim()
    assert res.is_coalesced() == ref.is_coalesced()
    utils.gems_assert_close(res.to_dense(), ref.to_dense(), dtype)


@pytest.mark.underscore_sparse_sum_backward
@pytest.mark.parametrize("shape,sparse_dim,nnz,dims", SUM_BWD_CASES)
@pytest.mark.parametrize("coalesced", [True, False])
@pytest.mark.parametrize("dtype", SUM_BWD_DTYPES)
def test__sparse_sum_backward(shape, sparse_dim, nnz, dims, coalesced, dtype):
    if any(d >= sparse_dim for d in dims) and sparse_dim < len(shape):
        pytest.skip("hybrid case only sums sparse dims")
    inp = _make_sparse_coo(shape, sparse_dim, nnz, dtype, flag_gems.device)
    grad = torch.ops.aten._sparse_sum(inp, dims)
    ref = torch.ops.aten._sparse_sum_backward(grad, inp, dims)
    res = flag_gems._sparse_sum_backward(grad, inp, dims)
    _assert_sparse_close(res, ref, dtype)


@pytest.mark.underscore_sparse_sum_backward
def test__sparse_sum_backward_dense_grad():
    """Summing every sparse dim leaves a dense grad."""
    inp = _make_sparse_coo((8, 6, 4), 3, 80, torch.float32, flag_gems.device)
    dims = [0, 1, 2]
    grad = torch.ops.aten._sparse_sum(inp, dims)
    assert not grad.is_sparse
    ref = torch.ops.aten._sparse_sum_backward(grad, inp, dims)
    res = flag_gems._sparse_sum_backward(grad, inp, dims)
    _assert_sparse_close(res, ref, torch.float32)
